import { execFile } from 'node:child_process';

function runProcess(command, args, options = {}) {
  return new Promise((resolve, reject) => {
    const child = execFile(command, args, {
      cwd: options.cwd ?? process.cwd(),
      maxBuffer: 1024 * 1024 * 10,
    }, (error, stdout, stderr) => {
      if (error) {
        error.stderr = stderr;
        reject(error);
        return;
      }

      resolve(stdout.trim());
    });

    if (options.input) {
      child.stdin.end(options.input);
    }
  });
}

function triageBody(lines) {
  return [
    '> *This was generated by AI during triage.*',
    '',
    ...lines,
  ].join('\n');
}

function requireText(value, name) {
  if (!value || typeof value !== 'string') {
    throw new Error(`${name} is required`);
  }
  return value;
}

function prBody({ issueNumber, summary, validation, changedFiles, autoMerge }) {
  return [
    `Closes #${issueNumber}`,
    '',
    summary,
    '',
    '## Validation',
    validation?.commands?.length
      ? validation.commands.map((command) => `- ${command}`).join('\n')
      : '- not recorded',
    '',
    '## Changed Files',
    changedFiles.length
      ? changedFiles.map((file) => `- ${file}`).join('\n')
      : '- none recorded',
    '',
    `Auto-merge: ${autoMerge ? 'enabled' : 'disabled'}`,
  ].join('\n');
}

export function createCoordinatorGithubSideEffects(options = {}) {
  const issueClient = options.issueClient;
  const gitClient = options.gitClient;
  const pullRequestClient = options.pullRequestClient;
  const runEventLog = options.runEventLog;

  async function createComment({ repository, issueNumber, runId, body, summary }) {
    const comment = await issueClient.createComment({ repository, issueNumber, body });
    await runEventLog.append({
      runId,
      type: 'comment',
      summary,
    });
    return comment;
  }

  async function recordBlocker({ repository, issueNumber, runId, blocker }) {
    await runEventLog.append({
      runId,
      type: 'blocker',
      summary: blocker.message,
      blocker,
    });
    await createComment({
      repository,
      issueNumber,
      runId,
      summary: `Blocked #${issueNumber}: ${blocker.message}`,
      body: triageBody([
        '## Blocked',
        '',
        `- Reason: ${blocker.message}`,
        `- Next step: ${blocker.nextStep}`,
      ]),
    });
  }

  return {
    async publishCompletedRun(request) {
      const repository = requireText(request.repository, 'repository');
      const branch = requireText(request.branch, 'branch');
      const baseBranch = request.baseBranch ?? 'main';
      const changedFiles = request.changedFiles ?? [];
      const autoMerge = false;
      const validationStatus = request.validation?.status ?? 'not recorded';

      await createComment({
        repository,
        issueNumber: request.issueNumber,
        runId: request.runId,
        summary: `Work started for #${request.issueNumber}.`,
        body: triageBody([
          `## Work started`,
          '',
          `- Run: ${request.runId}`,
          `- Branch: ${branch}`,
        ]),
      });
      await runEventLog.append({
        runId: request.runId,
        type: validationStatus === 'passed' ? 'validation.passed' : 'validation.failed',
        summary: `Validation ${validationStatus}.`,
        validation: request.validation,
      });
      await createComment({
        repository,
        issueNumber: request.issueNumber,
        runId: request.runId,
        summary: `Validation ${validationStatus} for #${request.issueNumber}.`,
        body: triageBody([
          `## Validation ${validationStatus}`,
          '',
          ...(request.validation?.commands ?? []).map((command) => `- ${command}`),
        ]),
      });

      if (!request.allowPush) {
        const blocker = {
          type: 'push-disabled',
          message: 'Branch push is not allowed by coordinator policy.',
          nextStep: 'Enable push policy for this run or keep the branch local.',
        };
        await recordBlocker({
          repository,
          issueNumber: request.issueNumber,
          runId: request.runId,
          blocker,
        });
        return {
          status: 'blocked',
          branch,
          blockers: [blocker],
          autoMerge,
        };
      }

      try {
        await gitClient.pushBranch({ repository, branch });
      } catch (error) {
        const blocker = {
          type: 'push-failed',
          message: `Branch push failed: ${error.message}`,
          nextStep: 'Inspect Git credentials, remote permissions, and branch protection before retrying.',
        };
        await recordBlocker({
          repository,
          issueNumber: request.issueNumber,
          runId: request.runId,
          blocker,
        });
        return {
          status: 'blocked',
          branch,
          blockers: [blocker],
          autoMerge,
        };
      }
      if (!request.allowPullRequest) {
        const blocker = {
          type: 'pull-request-disabled',
          message: 'Pull request creation is not allowed by coordinator policy.',
          nextStep: 'Enable pull request policy for this run or inspect the pushed branch manually.',
        };
        await recordBlocker({
          repository,
          issueNumber: request.issueNumber,
          runId: request.runId,
          blocker,
        });
        return {
          status: 'blocked',
          branch,
          blockers: [blocker],
          autoMerge,
        };
      }

      let pullRequest;
      try {
        pullRequest = await pullRequestClient.createPullRequest({
          repository,
          title: request.title,
          headBranch: branch,
          baseBranch,
          body: prBody({
            issueNumber: request.issueNumber,
            summary: request.summary,
            validation: request.validation,
            changedFiles,
            autoMerge,
          }),
        });
      } catch (error) {
        const blocker = {
          type: 'pull-request-failed',
          message: `Pull request creation failed: ${error.message}`,
          nextStep: 'Inspect GitHub authentication and repository PR permissions before retrying.',
        };
        await recordBlocker({
          repository,
          issueNumber: request.issueNumber,
          runId: request.runId,
          blocker,
        });
        return {
          status: 'blocked',
          branch,
          blockers: [blocker],
          autoMerge,
        };
      }
      await runEventLog.append({
        runId: request.runId,
        type: 'pr',
        summary: `Pull request opened: ${pullRequest.url}`,
      });
      await createComment({
        repository,
        issueNumber: request.issueNumber,
        runId: request.runId,
        summary: `Pull request opened for #${request.issueNumber}.`,
        body: triageBody([
          '## Pull request opened',
          '',
          `- PR: ${pullRequest.url}`,
          `- Auto-merge: ${autoMerge ? 'enabled' : 'disabled'}`,
        ]),
      });

      return {
        status: 'pr-opened',
        branch,
        pullRequest,
        autoMerge,
      };
    },
  };
}

export function createGitBranchClient(options = {}) {
  const runGit = options.runGit ?? ((args) => runProcess('git', args, options.processOptions));

  return {
    async pushBranch({ branch }) {
      await runGit([
        'push',
        '--set-upstream',
        'origin',
        requireText(branch, 'branch'),
      ]);
      return { remoteBranch: `origin/${branch}` };
    },
  };
}

export function createGhPullRequestClient(options = {}) {
  const runGh = options.runGh ?? ((args, runOptions) => runProcess('gh', args, runOptions));

  return {
    async viewPullRequest({ repository, number }) {
      const output = await runGh([
        'pr',
        'view',
        String(requireText(String(number), 'number')),
        '--repo',
        requireText(repository, 'repository'),
        '--json',
        'number,url,state,mergedAt,mergeStateStatus,reviewDecision,statusCheckRollup',
      ]);

      return JSON.parse(output);
    },

    async createPullRequest({ repository, title, headBranch, baseBranch, body }) {
      const output = await runGh([
        'pr',
        'create',
        '--repo',
        requireText(repository, 'repository'),
        '--title',
        requireText(title, 'title'),
        '--head',
        requireText(headBranch, 'headBranch'),
        '--base',
        requireText(baseBranch, 'baseBranch'),
        '--body-file',
        '-',
        '--json',
        'number,url,state',
      ], { input: body });

      if (output.startsWith('{')) {
        return JSON.parse(output);
      }

      return {
        number: Number(output.match(/\/pull\/(\d+)/)?.[1] ?? 0),
        url: output.trim(),
        state: 'OPEN',
      };
    },
  };
}
